import facts from '../data/facts.json'

/** A short, sourced science fact for the home page (never generated by an LLM). */
export interface Fact {
  text_cs: string
  source_url: string
}

const FACTS = facts as Fact[]

/** A different fact on every page load. */
export function randomFact(): Fact {
  return FACTS[Math.floor(Math.random() * FACTS.length)]
}

/** "en.wikipedia.org" → "Wikipedia", "www.nobelprize.org" → "nobelprize.org" */
export function sourceName(url: string): string {
  const host = new URL(url).hostname.replace(/^www\./, '')
  if (host.endsWith('wikipedia.org')) return 'Wikipedia'
  return host
}
